L(12, "Voo cancelado: direitos", "Recht op compensatie bij vertraging.",
  ["Conhecer e reclamar os direitos de passageiro"],
  vocab=[V("v-recht-op","recht hebben op","ter direito a","expression"), V("v-maaltijdbon","maaltijdbon","voucher de refeição","noun","de"), V("v-claimen","claimen","reclamar (uma compensação)","verb")],
  ex=[("Bij lange vertraging heb je recht op compensatie.","Com um atraso longo tens direito a compensação."),("Onze vlucht is drie uur vertraagd.","O nosso voo está três horas atrasado."),("We kregen een maaltijdbon van tien euro.","Recebemos um voucher de refeição de dez euros."),("Je kunt de compensatie online claimen.","Podes reclamar a compensação online.")],
  review=["v-vlucht-vertraagd","v-geannuleerd","v-schadevergoeding","v-compensatie","v-omboeken"],
  cefr=C, exs=[
    MA([("recht hebben op","ter direito a"),("vertraagd","atrasado"),("maaltijdbon","voucher de refeição"),("claimen","reclamar")], "Direitos.", ["v-recht-op","v-vlucht-vertraagd","v-maaltijdbon","v-claimen"]),
    CO("text","Uw rechten als passagier", "Binnen de Europese Unie hebben passagiers rechten als hun vlucht veel vertraging heeft of wordt geannuleerd. Afhankelijk van de vertraging en de afstand heb je recht op eten en drinken, bijvoorbeeld een maaltijdbon, en soms op een hotel. Bij grote vertraging of annulering kun je ook een financiële compensatie claimen, tenzij er buitengewone omstandigheden waren, zoals extreem slecht weer.",
       [("Onde valem estes direitos?", ["*Na União Europeia","Em todo o mundo","Só nos Países Baixos"]),("O que se pode receber durante a espera?", ["*Comida e bebida (voucher)","Um carro","Nada"]),("Quando não há compensação financeira?", ["*Em circunstâncias extraordinárias, como tempo extremo","Nunca","Sempre"])],
       "Direitos gerais (consulte as regras exatas).", ["v-recht-op","v-maaltijdbon","v-claimen"]),
    TR("pt-nl","O nosso voo está três horas atrasado.", ["Onze vlucht is drie uur vertraagd","Onze vlucht heeft drie uur vertraging"], "vertraagd.", ["v-vlucht-vertraagd"]),
    TR("pt-nl","Tens direito a compensação.", ["Je hebt recht op compensatie","Jij hebt recht op compensatie"], "recht op.", ["v-recht-op"]),
    DL([("Grondpersoneel","Uw vlucht is geannuleerd. Kunnen we u omboeken naar morgen?","O seu voo foi cancelado. Podemos remarcá-lo para amanhã?"),("Reiziger","","")], ["*Ja, graag. Heb ik ook recht op een hotel voor vannacht?","Nee, ik wil vandaag vliegen, punt.|Pouco realista.","Ik ben geannuleerd.|Não faz sentido."], "Aceitar e perguntar pelos direitos.", ["v-recht-op","v-omboeken"]),
    FE(["Je","hebt","recht","voor","compensatie."], 3, "op", "recht op.", ["v-recht-op"]),
    FB("Je kunt de compensatie via de website ___.", ["claimen"], "Reclamar.", ["v-claimen"], choices=["claimen","omboeken","annuleren"], tr="Podes reclamar a compensação através do site."),
    AR("maaltijdbon","o voucher de refeição","de", "De bon.", ["v-maaltijdbon"]),
    LI("We kregen een maaltijdbon, maar die was maar tien euro.", ["We kregen een maaltijdbon, maar die was maar tien euro","We kregen een maaltijdbon maar die was maar tien euro"], "Recebemos um voucher de refeição, mas era só de dez euros.", "maar = só.", ["v-maaltijdbon"]),
    WO("Tens direito a um hotel.", ["Je","hebt","recht","op","een","hotel"], "Ordem.", ["v-recht-op"]),
  ], diff=4, mins=7)

